const fs = require("fs");
const path = require("path");
const zlib = require("zlib");
const payload = "";
const files = JSON.parse(zlib.gunzipSync(Buffer.from(payload, "base64")).toString("utf8"));
for (const file of files) {
  const target = path.join(process.cwd(), file.path);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (file.content_b64) fs.writeFileSync(target, Buffer.from(file.content_b64, "base64"));
  else fs.writeFileSync(target, file.content, "utf8");
}
console.log(`Brilhe CRM: ${files.length} arquivos preparados para o build.`);
